head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > M > setSelectedInfo]<br/>컴포넌트에서 아이템들의 선택/해제를 아이템 정보를 가진 객체 배열로 설정합니다.",
    "validation" : [        
        "infoArray(필수) 파라미터로 선택/해제 하려는 아이템들의 정보를 객체 배열로 설정합니다.",
        "index 속성값으로 선택/해제 하려는 아이템의 인덱스를 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "checked 속성값으로 아이템의 선택 상태를 true/false 값으로 설정합니다.",
        "setSelectedInfo() 메소드로 아이템의 선택이 변경되면 onchange 이벤트가 발생합니다. "
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
            target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox(eList);
}



scwin.btn_getSelectedInfo_onclick = function (e) {
    let rtn = target1.getSelectedInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("objArray:" +rtn);

    if (rtn) {
        rtn.forEach(function(item, index) {
            wf_body_bottom.getObj("scwin").setReturnValue((index+1)+" 번째 선택된 Item 의 label : " +item.label);
            wf_body_bottom.getObj("scwin").setReturnValue((index+1)+" 번째 선택된 Item 의 checked : " +item.checked);
        });          
    }
};



scwin.btn_setAll_onclick = function (e) {
    let itemarr = target1.getInfoArray();
    let rsltarr = [];

    for (let i = 0; i < itemarr.length; i++) {
        let obj = {};
        obj.index = itemarr[i].index;
        if (itemarr[i].checked == true)    
            obj.checked = false;
        else
            obj.checked = true;

        rsltarr.push(obj);
    }

    target1.setSelectedInfo(rsltarr);
};



scwin.btn_setOdd_onclick = function (e) {
    let itemarr = target1.getInfoArray();
    let rsltarr = [];

    for (let i = 0; i < itemarr.length; i++) {
        let obj = {};
        obj.index = itemarr[i].index;

        if (obj.index % 2 === 0) {
            if (itemarr[i].checked == true)    
                obj.checked = false;
            else
                obj.checked = true;

            rsltarr.push(obj);
        }
    }

    target1.setSelectedInfo(rsltarr);
};


scwin.target1_onchange = function(info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");    
}
